function parseJsonLoose(value) {
  if (value == null || value === '') return null;
  if (typeof value === 'object') return value;
  let s = String(value).trim();
  if (!s) return null;
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  for (let i = 0; i < 3; i++) {
    const start = s[0];
    if (start !== '{' && start !== '[') break;
    try {
      const parsed = JSON.parse(s);
      if (typeof parsed === 'string') {
        s = parsed.trim();
        continue;
      }
      return parsed;
    } catch (e) {
      break;
    }
  }
  return null;
}

function parseKvBlob(text) {
  if (!text || typeof text !== 'string') return {};
  const known = {
    action: 'action',
    displayname: 'displayName',
    display_name: 'displayName',
    clientname: 'displayName',
    firmname: 'displayName',
    storename: 'storeName',
    store_name: 'storeName',
    storeid: 'storeName',
    documentname: 'documentName',
    document_name: 'documentName',
    documentid: 'documentName',
    docname: 'documentName',
    query: 'query',
    question: 'query',
    force: 'force'
  };
  const names = Object.keys(known).sort((a, b) => b.length - a.length);
  const re = new RegExp('\\b(' + names.join('|') + ')\\s*[=:]\\s*', 'gi');
  const matches = [];
  let m;
  while ((m = re.exec(text))) {
    matches.push({ raw: m[1], valueStart: m.index + m[0].length, matchStart: m.index });
  }
  if (!matches.length) return {};
  const out = {};
  for (let i = 0; i < matches.length; i++) {
    const end = i + 1 < matches.length ? matches[i + 1].matchStart : text.length;
    let val = text.slice(matches[i].valueStart, end).trim().replace(/[,;]\s*$/g, '').trim();
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1).trim();
    }
    const canon = known[matches[i].raw.toLowerCase()];
    if (canon && val !== '') out[canon] = val;
  }
  return out;
}

function firstNonEmpty(obj, keys) {
  for (const k of keys) {
    if (obj[k] == null) continue;
    const v = typeof obj[k] === 'object' ? obj[k] : String(obj[k]).trim();
    if (v === '' || v == null || v === 'null' || v === 'undefined') continue;
    return obj[k];
  }
  return '';
}

function asBool(value) {
  if (value === true || value === 1) return true;
  const s = String(value == null ? '' : value).trim().toLowerCase();
  return ['true', '1', 'yes', 'y', '-f', '--force', 'force'].includes(s);
}

const ALIASES = {
  list_documents: 'list_docs',
  list_docs: 'list_docs',
  listdocs: 'list_docs',
  documents: 'list_docs',
  list_document: 'list_docs',
  delete_document: 'delete_doc',
  delete_doc: 'delete_doc',
  deletedoc: 'delete_doc',
  remove_doc: 'delete_doc',
  remove_document: 'delete_doc',
  delete_store: 'delete_store',
  deletestore: 'delete_store',
  remove_store: 'delete_store',
  destroy_store: 'delete_store',
  drop_store: 'delete_store',
  wipe_store: 'delete_store'
};

const src = $input.first().json || {};
const layers = [src];

for (const key of Object.keys(src)) {
  const parsed = parseJsonLoose(src[key]);
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
    layers.push(parsed);
    const nested = parseJsonLoose(parsed.query);
    if (nested && typeof nested === 'object' && !Array.isArray(nested)) layers.push(nested);
  }
  const kv = parseKvBlob(typeof src[key] === 'string' ? src[key] : '');
  if (Object.keys(kv).length) layers.push(kv);
}

const merged = Object.assign({}, ...layers);

let action = String(firstNonEmpty(merged, ['action', 'operation', 'op', 'intent', 'command']) || '').trim().toLowerCase();
if (ALIASES[action]) action = ALIASES[action];

let displayName = String(firstNonEmpty(merged, ['displayName', 'display_name', 'clientName', 'firmName']) || '').trim();
let storeName = String(firstNonEmpty(merged, ['storeName', 'store_name', 'storeId', 'store']) || '').trim();
let documentName = String(firstNonEmpty(merged, ['documentName', 'document_name', 'documentId', 'document', 'docName', 'doc']) || '').trim();
let query = firstNonEmpty(merged, ['query', 'question', 'prompt', 'text', 'message']);
query = typeof query === 'string' ? query.trim() : (query && typeof query === 'object' ? '' : String(query || '').trim());
if (query === 'null' || query === 'undefined') query = '';
let force = asBool(firstNonEmpty(merged, ['force', 'f', 'confirm']));

const rawName = String(firstNonEmpty(merged, ['name']) || '').trim();
if (rawName.startsWith('fileSearchStores/') && rawName.includes('/documents/')) documentName = documentName || rawName;
else if (rawName.startsWith('fileSearchStores/')) storeName = storeName || rawName;
else if (!displayName && rawName) displayName = rawName;

const queryObj = parseJsonLoose(query);
if (queryObj && typeof queryObj === 'object' && !Array.isArray(queryObj)) {
  if (!action) {
    action = String(queryObj.action || queryObj.operation || '').trim().toLowerCase();
    if (ALIASES[action]) action = ALIASES[action];
  }
  if (!displayName) displayName = String(queryObj.displayName || '').trim();
  if (!storeName) storeName = String(queryObj.storeName || '').trim();
  if (!documentName) documentName = String(queryObj.documentName || queryObj.document || '').trim();
  if (!force) force = asBool(queryObj.force);
  query = String(queryObj.query || queryObj.question || '').trim();
}

const kvFromQuery = parseKvBlob(query);
if (Object.keys(kvFromQuery).length) {
  if (!action && kvFromQuery.action) {
    action = String(kvFromQuery.action).trim().toLowerCase();
    if (ALIASES[action]) action = ALIASES[action];
  }
  if (!displayName && kvFromQuery.displayName) displayName = String(kvFromQuery.displayName).trim();
  if (!storeName && kvFromQuery.storeName) storeName = String(kvFromQuery.storeName).trim();
  if (!documentName && kvFromQuery.documentName) documentName = String(kvFromQuery.documentName).trim();
  if (!force && kvFromQuery.force != null) force = asBool(kvFromQuery.force);
  if (action === 'query' && kvFromQuery.query) query = String(kvFromQuery.query).trim();
  else if (action !== 'query') query = kvFromQuery.query ? String(kvFromQuery.query).trim() : '';
}

const blob = `${action} ${displayName} ${storeName} ${documentName} ${query} ${JSON.stringify(src)}`.toLowerCase();
const VALID = ['list', 'create', 'get', 'query', 'list_docs', 'delete_doc', 'delete_store'];

if (!VALID.includes(action)) {
  if (/\b(docs?|documents?|files)\b/.test(blob) && /\b(list|show|give|what|which)\b/.test(blob)) action = 'list_docs';
  else if (/\b(delete|remove)\b/.test(blob) && /\b(docs?|document|file)\b/.test(blob)) action = 'delete_doc';
  else if (/\b(delete|remove|destroy|wipe|drop)\b/.test(blob) && /\b(store|rag)\b/.test(blob)) action = 'delete_store';
  else if (/\b(list|show|inventor(?:y|ies)|existing)\b/.test(blob) && /\b(store|stores|rag|index)\b/.test(blob)) action = 'list';
  else if (/\b(create|new|setup|set up)\b/.test(blob) && /\b(store|client|firm|rag)\b/.test(blob)) action = 'create';
  else if (storeName && query) action = 'query';
  else if (storeName) action = 'get';
  else if (query.toLowerCase() === 'list' || action === 'list') action = 'list';
}

if (action === 'list' && /\b(docs?|documents?|files)\b/.test(blob)) action = 'list_docs';

if ((action === 'list' || action === 'list_docs' || action === 'create' || action === 'get' || action === 'delete_doc' || action === 'delete_store') && (parseJsonLoose(query) || parseKvBlob(query).action || query.includes('"action"'))) query = '';
if (action === 'list' && /^\s*list\b/i.test(query)) query = '';

const inMatch = `${displayName} ${query}`.match(/\b(?:in|from|for)\s+["']?(.+?)["']?\s*$/i);
if (inMatch && !storeName && !displayName) {
  displayName = inMatch[1].replace(/\s+(RAG|store|stores)\s*$/i, '').trim();
}

if (storeName && !storeName.startsWith('fileSearchStores/') && /^[a-z0-9-]{8,}$/i.test(storeName)) {
  storeName = 'fileSearchStores/' + storeName;
}

if (displayName.startsWith('fileSearchStores/')) {
  if (!storeName) storeName = displayName;
  displayName = '';
}

if (documentName && !documentName.includes('/documents/') && storeName) {
  documentName = storeName.replace(/\/$/, '') + '/documents/' + documentName.replace(/^documents\//, '');
}

if (query === '-f' || query.toLowerCase() === 'force') {
  force = true;
  if (action !== 'query') query = '';
}

return [{ json: { action, displayName, storeName, documentName, query, force } }];

const body = $input.first().json || {};
const stores = (body.fileSearchStores || []).map(s => ({
  storeName: s.name,
  displayName: s.displayName,
  activeDocumentsCount: s.activeDocumentsCount,
  pendingDocumentsCount: s.pendingDocumentsCount,
  failedDocumentsCount: s.failedDocumentsCount
}));

return [{
  json: {
    ok: true,
    action: 'list',
    stores,
    nextPageToken: body.nextPageToken || '',
    hint: 'Use storeName (fileSearchStores/...) for get or query. Match displayName to the client or firm.'
  }
}];

const created = $input.first().json || {};
const storeName = created.name || '';
const displayName = created.displayName || $('Normalize Tool Input').item.json.displayName;

return [{
  json: {
    ok: !!storeName,
    action: 'create',
    storeName,
    displayName,
    nextStep: 'Store is empty until files are ingested. Open this workflow FORM, upload documents, paste storeName into Add to existing store?. Then call action=query with this storeName.',
    ingestHint: 'Agents cannot upload files. Form ingest is required before RAG answers will have sources.'
  }
}];

const store = $input.first().json || {};
const requested = $('Normalize Tool Input').item.json.storeName;
const active = Number(store.activeDocumentsCount || 0);

return [{
  json: {
    ok: !!store.name,
    action: 'get',
    storeName: store.name || requested,
    displayName: store.displayName || '',
    activeDocumentsCount: store.activeDocumentsCount || '0',
    pendingDocumentsCount: store.pendingDocumentsCount || '0',
    failedDocumentsCount: store.failedDocumentsCount || '0',
    readyForChat: active > 0,
    hint: active > 0
      ? 'Store has indexed documents. Call action=query with this storeName and the user question.'
      : 'No indexed documents yet. Tell the user to ingest via the FORM using this storeName.'
  }
}];

const raw = $input.first().json || {};
const input = $('Normalize Tool Input').item.json;
const candidate = (raw.candidates && raw.candidates[0]) || {};
const parts = (candidate.content && candidate.content.parts) || [];
const answer = parts.map(p => p.text).filter(Boolean).join('\n');

return [{
  json: {
    ok: !!answer,
    action: 'query',
    storeName: input.storeName,
    query: input.query,
    answer: answer || '',
    grounding: candidate.groundingMetadata || null,
    hint: answer
      ? 'Answer is grounded in the selected File Search store. Cite storeName if useful.'
      : 'Empty answer. Call action=get on this storeName. If activeDocumentsCount is 0, send the user to the FORM.'
  }
}];

const input = $input.first().json || {};
return [{ json: {
  ok: false,
  error: 'invalid_action',
  got: input.action || '',
  message: 'Set action to list, create, get, query, list_docs, delete_doc, or delete_store. Do not put JSON in query.',
  example: { action: 'list_docs', storeName: 'fileSearchStores/...', documentName: '', query: '', force: false },
  received: input
} }];

function metaValue(doc, key) {
  const rows = doc.customMetadata || [];
  const hit = rows.find(m => m && m.key === key);
  if (!hit) return '';
  return String(hit.stringValue || hit.numericValue || hit.stringListValue || '').trim();
}

const body = $input.first().json || {};
const input = $('Normalize Tool Input').item.json;
const documents = (body.documents || []).map(d => {
  const fileName = metaValue(d, 'source_file') || d.displayName || '';
  const documentName = d.name || '';
  return {
    fileName,
    documentName,
    label: fileName ? `${fileName} — ${documentName}` : documentName,
    geminiDisplayName: d.displayName || '',
    mimeType: d.mimeType || '',
    state: d.state || '',
    sizeBytes: d.sizeBytes || '',
    createTime: d.createTime || '',
    updateTime: d.updateTime || ''
  };
});

return [{ json: {
  ok: true,
  action: 'list_docs',
  storeName: input.storeName,
  displayName: input.displayName || '',
  documents,
  listing: documents.map(d => d.label),
  nextPageToken: body.nextPageToken || '',
  hint: 'Show listing / fileName (customMetadata source_file) to the user. Use documentName with action=delete_doc. Do not show geminiDisplayName unless fileName is empty.'
} }];

const input = $input.first().json || {};
return [{ json: {
  ok: false,
  error: 'storeName_required',
  action: 'list_docs',
  displayName: input.displayName || '',
  message: 'list_docs needs storeName (fileSearchStores/...). Call action=list, match the client/firm displayName, then retry list_docs with that storeName.'
} }];

const input = $('Normalize Tool Input').item.json;
return [{ json: {
  ok: true,
  action: 'delete_doc',
  documentName: input.documentName,
  storeName: input.storeName || '',
  hint: 'Document and its chunks were deleted. Call list_docs to confirm. Re-ingest via the FORM if you still need this file.'
} }];

const input = $input.first().json || {};
return [{ json: {
  ok: false,
  error: 'documentName_required',
  action: 'delete_doc',
  storeName: input.storeName || '',
  query: input.query || '',
  message: 'delete_doc needs documentName like fileSearchStores/.../documents/.... Call action=list_docs first, pick the document, then retry delete_doc.'
} }];

const input = $('Normalize Tool Input').item.json;
return [{ json: {
  ok: true,
  action: 'delete_store',
  storeName: input.storeName,
  displayName: input.displayName || '',
  hint: 'Store and all documents were deleted. Clear this store from the session. Call action=list to confirm it is gone.'
} }];

const input = $input.first().json || {};
return [{ json: {
  ok: false,
  error: 'force_required',
  action: 'delete_store',
  storeName: input.storeName || '',
  displayName: input.displayName || '',
  message: 'Refused. Deleting a store removes ALL documents. Confirm with the user, then call again with action=delete_store, the same storeName, and force=true (or -f).'
} }];

const input = $input.first().json || {};
return [{ json: {
  ok: false,
  error: 'storeName_required',
  action: 'delete_store',
  message: 'delete_store needs storeName (fileSearchStores/...) and force=true. Call action=list first, then retry.'
} }];
